          "html": "Ниже три <b>независимых</b> учебных случая, а не цепочка одного запуска. Для каждого установим последнее подтверждённое событие: файл прочитан, запрос запуска принят, загрузчик начал работу или управление уже дошло до main. Условные имена не означают, что нужно менять системные пути."
