          "html": "Допустим, проект работает в старом build, но не собирается в новом каталоге. Возможно, прежняя сборка использовала оставшийся сгенерированный файл. Поэтому различаем три свойства: инкрементальная сборка обновляет нужные результаты; сборка в новом каталоге не опирается на старые результаты этого дерева; побитовая воспроизводимость требует одинаковых байтов оговорённых артефактов (сохраняемых результатов сборки: программ, библиотек, пакетов) при восстановлении документированных входов и среды."
