          "html": "Общий CMakePresets.json обычно хранят в Git. Личные настройки, например путь к локально установленному инструменту, можно вынести в CMakeUserPresets.json и не коммитить его. Локальный путь /opt/compiler/bin/c++ у одного человека не означает, что у другого по нему находится тот же компилятор. Секреты также не следует записывать в общий пресет или публиковать вместе с диагностикой."
