          "html": "Toolchain (набор инструментов сборки) включает не только C++-компилятор, но и связанные инструменты, например компоновщик. CMake toolchain file загружается достаточно рано, чтобы задать соответствующие пути и свойства целевой системы. При кросс-компиляции программа собирается не для той системы, на которой выполняется сборка; тогда также важны целевые заголовки и библиотеки. Сам файл с путями не фиксирует содержимое этих инструментов."
