          "type": "text",
          "html": "compile_commands.json помогает увидеть фактическую команду компиляции каждого исходника: флаги, определения макросов и пути заголовков. Его используют анализаторы и редакторы. Но он не является полным рецептом сборки: например, не описывает все команды компоновки и происхождение скачанных зависимостей. Для сравнения двух сборок смотрим конкретные команды, версии инструментов и выбранные входы, а не только название пресета."
