      "substation": "linux-diagnostics",
      "title": "Почему один бинарник ведёт себя по-разному при запуске",
      "lead": "Программа открывает config/app.conf в терминале, но не находит его как служба. Прежде чем менять C++, восстановим условия двух запусков.",
