          "type": "text",
          "html": "ASan (AddressSanitizer) добавляет проверки при сборке и помогает найти, например, выход за границы памяти или использование после освобождения. UBSan проверяет поддерживаемые виды неопределённого поведения. Они видят только выполненные пути и не доказывают отсутствие остальных ошибок. TSan предназначен для гонок данных; многопоточность и ограничения этой проверки подробно разберём на станции 6."
