          "html": "<strong>1. Условие.</strong> Есть входные целые числа: −5, 35 и 140. Нужно ограничить каждое диапазоном 0…100: получим 0, 35 и 100. Вынесем вычисление в отдельную функцию clamp_percent и отдельный .cpp. Алгоритм прост специально: задача здесь — проследить, что знает компилятор и что ещё должен получить линкер."
