          "type": "text",
          "html": "<strong>Файл percent.cpp.</strong> Значение передаётся по значению: изменение локального параметра не изменило бы аргумент вызывающего, хотя здесь мы просто возвращаем результат. Сложений и умножений нет, поэтому даже крайние значения int безопасно сравниваются с границами."
